import { Router } from 'express';
import { z } from 'zod';
import { getConfigManager } from '../services/ConfigManager';
import type { ErrorResponse } from '../types/api-responses';
import {
  THEME_PREFERENCES,
  type ThemePreferenceResource,
} from '../types/theme-preference';
import { createLogger } from '../utils/logger';

const log = createLogger('PreferenceRoutes');

const ThemePreferenceUpdateSchema = z
  .object({ preference: z.enum(THEME_PREFERENCES) })
  .strict();

export const createPreferencesRouter = () => {
  const router = Router();
  router
    .route('/preferences/theme')
    .get((_req, res) => {
      res.json({
        preference: getConfigManager().getThemePreference(),
      } satisfies ThemePreferenceResource);
    })
    .put((req, res) => {
      const update = ThemePreferenceUpdateSchema.safeParse(req.body);
      if (!update.success) {
        res.status(400).json({
          error: 'Choose a light, dark or system theme.',
        } satisfies ErrorResponse);
        return;
      }
      try {
        getConfigManager().setThemePreference(update.data.preference);
      } catch (error) {
        log.error('Could not save the theme preference', error);
        res.status(500).json({
          error: 'Rivet could not save your theme.',
        } satisfies ErrorResponse);
        return;
      }
      res.json({
        preference: update.data.preference,
      } satisfies ThemePreferenceResource);
    });
  return router;
};
